'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const def = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // 1. Older detached flight settling must not detach/overwrite newer flight.
  {
    const gates = [def(), def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].resolve('old'); assert.equal(await a, 'old');
    const b2 = c.get('k'); // must join flight b
    gates[1].resolve('new');
    assert.equal(await b, 'new'); assert.equal(await b2, 'new');
    assert.equal(calls, 2); assert.equal(await c.get('k'), 'new'); assert.equal(c.size, 1);
  }
  // 2. Rejections not cached; retry works; sync throw and non-Error reasons.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load() { calls++; if (calls === 1) throw 'boom'; return 'ok'; } });
    const [r1, r2] = [c.get('k'), c.get('k')];
    await assert.rejects(r1, x => x === 'boom'); await assert.rejects(r2, x => x === 'boom');
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  // 3. Detached rejecting flight must not detach newer flight.
  {
    const gates = [def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    const b2 = c.get('k'); gates[1].resolve('v');
    assert.equal(await b2, 'v'); assert.equal(calls, 2);
  }
  // 4. set during load wins; old completion doesn't restart TTL; expiry -> new load.
  {
    let t = 0; const gate = def(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? gate.promise : 'fresh') });
    const a = c.get('k'); await tick();
    c.set('k', 'set');
    t = 5; gate.resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'set');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'fresh'); assert.equal(calls, 2);
  }
  // 5. clear during load; ttl 0 never reuses settled values but dedupes.
  {
    const gate = def(); let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 0, load: () => (++calls === 1 ? gate.promise : 'v' + calls) });
    const a = c.get('k'), a2 = c.get('k'); await tick(); c.clear();
    gate.resolve('old'); assert.equal(await a, 'old'); assert.equal(await a2, 'old');
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(await c.get('k'), 'v3');
  }
  // 6. load synchronously invalidates/sets itself; reads own key joins flight.
  {
    let c; let calls = 0; let joined;
    c = createCache({ now: () => 0, load(k) { calls++; if (calls === 1) { joined = c.get(k); c.set(k, 'manual'); return 'loaded'; } return 'x'; } });
    assert.equal(await c.get('k'), 'loaded');
    assert.equal(await joined, 'loaded');
    assert.equal(await c.get('k'), 'manual'); assert.equal(calls, 1);
  }
  console.log('all ok');
})().catch(e => { console.error(e); process.exit(1); });

